<script setup>
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});const state=reactive({rows:[],stats:{},pagination:{},filters:{search:'',payment_status:'',payment_method:'',date:''}});const loading=ref(true),error=ref('');let abort,timer;
async function load(url=location.href,push=false){abort?.abort();abort=new AbortController();loading.value=true;error.value='';try{const r=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),d=await r.json();if(!r.ok)throw new Error(d.message||`Request failed (${r.status})`);state.rows=d.payments||[];state.stats=d.stats||{};state.pagination=d.pagination||{};state.filters={search:'',payment_status:'',payment_method:'',date:'',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{loading.value=false}}
function url(){const u=new URL(props.indexUrl,location.origin);for(const[k,v]of Object.entries(state.filters))if(v)u.searchParams.set(k,v);return u.href}function apply(){load(url(),true)}function search(){clearTimeout(timer);timer=setTimeout(apply,350)}function page(l){if(l.url)load(l.url,true)}function pop(){load(location.href)}
async function remove(row){let yes=true;if(window.Swal){const r=await window.Swal.fire({title:'Delete payment?',text:`Delete transaction ${row.transaction_id}?`,icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});yes=r.isConfirmed}else yes=confirm('Delete payment?');if(!yes)return;const f=document.createElement('form');f.method='POST';f.action=row.delete_url;f.innerHTML=`<input name="_token" value="${props.csrf}"><input name="_method" value="DELETE">`;document.body.append(f);f.submit()}
onMounted(()=>{const p=new URLSearchParams(location.search);state.filters={search:p.get('search')||'',payment_status:p.get('payment_status')||'',payment_method:p.get('payment_method')||'',date:p.get('date')||''};if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{clearTimeout(timer);abort?.abort();window.removeEventListener('popstate',pop)});
</script>
<template><section class="payments-hero"><div class="payments-hero-content"><span class="payments-hero-badge"><i class="bi bi-credit-card"></i> Payment Operations</span><h1>Every payment, under control.</h1><p>Manage transactions, payment methods and payment status from one organised workspace.</p></div><div class="payments-hero-mark"><i class="bi bi-wallet2"></i></div></section><section class="payments-stats"><div class="payment-stat-card stat-blue"><div class="payment-stat-content"><span>Total Payments</span><strong>{{ state.stats.total??'—' }}</strong></div><div class="payment-stat-icon"><i class="bi bi-credit-card"></i></div></div><div class="payment-stat-card stat-orange"><div class="payment-stat-content"><span>Pending</span><strong>{{ state.stats.pending??'—' }}</strong></div><div class="payment-stat-icon"><i class="bi bi-hourglass-split"></i></div></div><div class="payment-stat-card stat-green"><div class="payment-stat-content"><span>Paid</span><strong>{{ state.stats.paid??'—' }}</strong></div><div class="payment-stat-icon"><i class="bi bi-check-circle"></i></div></div><div class="payment-stat-card stat-purple"><div class="payment-stat-content"><span>Total Revenue</span><strong>${{ Number(state.stats.revenue||0).toFixed(2) }}</strong></div><div class="payment-stat-icon"><i class="bi bi-cash-stack"></i></div></div></section><section class="dashboard-panel payments-panel"><div class="payments-panel-header"><div class="payments-heading-content"><span class="eyebrow">Payment Directory</span><h5>All Payments</h5><p>Search, filter and review payment transactions.</p></div><div class="payments-header-action"><a :href="createUrl" class="payments-add-btn"><i class="bi bi-plus-lg"></i> Add Payment</a></div></div><form class="payment-filters" @submit.prevent="apply"><div class="payment-filter-group payment-filter-search"><label>Search</label><div class="payment-search-field"><i class="bi bi-search"></i><input v-model="state.filters.search" placeholder="Transaction, order, customer..." @input="search"></div></div><div class="payment-filter-group"><label>Payment Status</label><select v-model="state.filters.payment_status" class="payment-filter-select"><option value="">All Status</option><option v-for="s in ['pending','paid','failed','refunded']" :key="s">{{ s }}</option></select></div><div class="payment-filter-group"><label>Payment Method</label><select v-model="state.filters.payment_method" class="payment-filter-select"><option value="">All Methods</option><option v-for="s in ['cash_on_delivery','credit_card','debit_card','paypal']" :key="s">{{ s }}</option></select></div><div class="payment-filter-group"><label>Date</label><div class="payment-date-field"><input v-model="state.filters.date" type="date" name="date"></div></div><div class="payment-filter-actions"><button class="payment-filter-btn"><i class="bi bi-funnel"></i> Filter</button><button v-if="Object.values(state.filters).some(Boolean)" type="button" class="payment-clear-filter" @click="state.filters={search:'',payment_status:'',payment_method:'',date:''};apply()">Clear</button></div></form><div v-if="error" class="payments-alert payments-alert-error"><span>{{ error }}</span><button @click="load()">Retry</button></div><div class="payments-results"><div class="payments-table-wrap"><table class="payments-table"><thead><tr><th class="payments-col-id">#</th><th class="payments-col-transaction">Transaction</th><th class="payments-col-customer">Customer</th><th class="payments-col-order">Order</th><th class="payments-col-amount">Amount</th><th class="payments-col-method">Method</th><th class="payments-col-status">Status</th><th class="payments-col-date">Date</th><th class="payments-col-actions">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="9" class="text-center py-4">Loading payments…</td></tr><tr v-for="p in state.rows" v-else :key="p.id"><td><span class="payment-id">#{{ p.id }}</span></td><td><div class="payment-transaction-cell"><div class="payment-transaction-icon"><i class="bi bi-receipt"></i></div><div class="payment-transaction-info"><strong>{{ p.transaction_id }}</strong><small>Transaction</small></div></div></td><td><div class="payment-customer-cell"><div class="payment-customer-avatar">{{ (p.customer||'C').slice(0,1).toUpperCase() }}</div><div class="payment-customer-info"><strong>{{ p.customer||'Customer' }}</strong><small>{{ p.email||'—' }}</small></div></div></td><td><div class="payment-order-cell"><div class="payment-order-icon"><i class="bi bi-cart-check"></i></div><div class="payment-order-info"><strong>{{ p.order_number||'—' }}</strong><small>{{ p.book||'Unknown book' }}</small></div></div></td><td><strong class="payment-amount">${{ p.amount }}</strong></td><td>{{ p.payment_method?.replaceAll('_',' ') }}</td><td><span class="payment-status" :class="`payment-status-${p.payment_status}`"><i class="bi bi-circle-fill"></i>{{ p.payment_status }}</span></td><td>{{ p.date }}</td><td><div class="payment-actions"><a :href="p.show_url" class="payment-action action-view" title="View"><i class="bi bi-eye"></i></a><a :href="p.edit_url" class="payment-action action-edit" title="Edit"><i class="bi bi-pencil"></i></a><button class="payment-action action-delete" title="Delete" @click="remove(p)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!loading&&!state.rows.length"><td colspan="9"><div class="payment-empty"><i class="bi bi-credit-card"></i><strong>No payments found</strong><span>Try changing your filters.</span></div></td></tr></tbody></table></div></div><div v-if="state.pagination.total>10" class="payment-pagination"><span>Showing {{ state.pagination.first_item }} to {{ state.pagination.last_item }} of {{ state.pagination.total }} payments</span><nav><button v-for="(l,i) in state.pagination.links" :key="i" class="payment-pager-btn" :class="{active:l.active,disabled:!l.url}" :disabled="!l.url" @click="page(l)" v-html="l.label.replace('&laquo;','‹').replace('&raquo;','›')"></button></nav></div></section></template>
